scripts.房客对话1.txt:
//房客1对话

	If ($Map055_1fangke == 1) @Talk1;
		
	Say("海藤先生：自从诗学没落，词道兴行，文词意境再难现盛唐气势……叹哉，惜哉！");
	Say("海藤先生：而自东坡以下，脱小家气质者，唯称稼轩矣。");
	Assign($Map055_1fangke,1);
	Return;
	
@Talk1:
	Say("海藤先生：<enter>秦时明月汉时关，万里长征人未还。<enter>但使龙城飞将在，不叫胡马度阴山。");
	Say("海藤先生：“秦”句为首句，起征纵横千年；“万”句为颔句，单一个“万”字，衔先古之气势，已道尽悲凉。只可惜，颈句、尾句虽气概有余，然见识略浅……");
	Say("海藤先生：想我大宋兵精将良，却因朝廷怯懦，君上昏庸……纵有雄心万丈，却无用武之地！叹哉，惜哉！");
	Return;

scripts.姚公子对话.txt:
// 与姚公子的同伴对话

	If ($Event == 307) @Event307;
	Return;
	
@Event307:
	Say("独孤剑：如果你以后再敢鱼肉百姓，我可饶不了你！", 5);
	Say("姚公子：不敢，不敢，我再也不敢啦……", 71);
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 300) @Event300;
	If ($Event == 301) @Event301;
	If ($Event == 307) @Event307;	
	If ($Event == 360) @Event360;
	
	Return;
	
@Event300:
	Say("张琳心：咱们四处问问，看看有什么李三的消息。", 21);
	Return;

@Event301:
	Say("张琳心：怎样才能救李三呢？", 21);
	Return;
	
@Event307:
	Say("张琳心：我们快去大牢救李三吧。", 21);
	Return;		
	
@Event360:
	Say("张琳心：我们快去找那个华山派弟子吧。", 21);
	Say("独孤剑：他下山的时候说去妓院，此刻可能还在那里。", 1);
	Return;

scripts.房客洁琳对话.txt:
